import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 퇴직금 시뮬레이션은 최근 확정(마감·전표처리) 급여 3건의 지급 합계 평균을 월 평균 급여로 보고,
// 예상 퇴직금 = 월 평균 급여 x (근속일수 / 365) 로 계산한다. 조회용이며 저장하지 않는다.
const AVERAGE_PAYROLL_COUNT = 3;
const DAYS_PER_YEAR = 365;

function isValidDateText(text: string): boolean {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!m) {
    return false;
  }
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12 || day < 1) {
    return false;
  }
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const lengths = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= lengths[month - 1];
}

@Controller('api/v1')
export class FnSfr03206Controller {
  @Get('/severance-simulations')
  async getSeveranceSimulation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const retirementDate = query['retirementDate'];
    if (typeof retirementDate !== 'string' || retirementDate === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '퇴직 예정일을 입력하세요.');
    }
    if (!isValidDateText(retirementDate)) {
      throw new ApiError(422, 'INVALID_RETIREMENT_DATE', '퇴직 예정일이 유효하지 않습니다.');
    }
    return transaction(async (db) => {
      const employees = await db.query(
        `SELECT CAST(CAST(:retirementDate AS date) - hire_date AS integer) AS "serviceDays"
           FROM employee
          WHERE employee_id = CAST(:userId AS bigint)`,
        { retirementDate, userId: user.id },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '임직원 정보를 찾을 수 없습니다.');
      }
      const serviceDays = employees[0]['serviceDays'];
      if (serviceDays === null || serviceDays === undefined || Number(serviceDays) <= 0) {
        throw new ApiError(422, 'INVALID_RETIREMENT_DATE', '퇴직 예정일이 유효하지 않습니다.');
      }
      const averages = await db.query(
        `SELECT AVG(t.total_payment_amount) AS "averagePay"
           FROM (
                 SELECT p.total_payment_amount
                   FROM payroll p
                   JOIN payday d ON d.payday_id = p.payday_id
                  WHERE p.employee_id = CAST(:userId AS bigint)
                    AND d.status IN ('마감', '전표처리')
                    AND p.total_payment_amount IS NOT NULL
                  ORDER BY d.pay_date DESC
                  LIMIT :limit
                ) t`,
        { userId: user.id, limit: AVERAGE_PAYROLL_COUNT },
      );
      const averagePay = averages.length > 0 && averages[0]['averagePay'] !== null
        ? Number(averages[0]['averagePay'])
        : 0;
      const estimatedSeverance = Math.round((averagePay * Number(serviceDays)) / DAYS_PER_YEAR);
      return { estimatedSeverance };
    });
  }
}

