import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  DateInput,
  LookupSelect,
  RefName,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

export default function FnSfr03206Page({ role, notify }: PageProps) {
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [applied, setApplied] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [retirementDate, setRetirementDate] = useState('');
  const [result, setResult] = useState<number | undefined>(undefined);

  const payrolls = useData<Page | undefined>(
    async () => {
      if (applied === '') {
        return undefined;
      }
      return call<Page>('GET', '/payrolls', role, undefined, { paydayId: applied, page, size: 20 });
    },
    [applied, page],
  );

  const rows: Row[] = payrolls.data ? payrolls.data.items : [];

  async function simulate() {
    if (retirementDate === '') {
      throw new Error('퇴직 예정일을 입력하세요.');
    }
    const res = await call<Row>('GET', '/severance-simulations', role, undefined, { retirementDate });
    setResult(Number(res['estimatedSeverance']));
    notify('퇴직금을 계산했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>예상 퇴직금</h2>
        <Tiles items={[['시뮬레이션 결과', result === undefined ? '-' : <Num value={result} />]]} />
        <Band>
          <button
            onClick={() => {
              setResult(undefined);
              setOpen(true);
            }}
          >
            퇴직금 시뮬레이션
          </button>
        </Band>
      </section>
      <section className="box span-8">
        <h2>급여명세서</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(paydayId);
          }}
          onReset={() => {
            setPaydayId('');
            setApplied('');
            setPage(0);
          }}
        >
          <Field label="급여 지급일 ID">
            <LookupSelect table="payday" role={role} value={paydayId} onChange={setPaydayId} />
          </Field>
        </Filters>
        <Band total={payrolls.data ? payrolls.data.total : 0} />
        <DataTable
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'totalPaymentAmount', label: '지급 합계', render: (r) => <Num value={r['totalPaymentAmount']} /> },
            { key: 'totalDeductionAmount', label: '공제 합계', render: (r) => <Num value={r['totalDeductionAmount']} /> },
            { key: 'netPayAmount', label: '실수령액', render: (r) => <Num value={r['netPayAmount']} /> },
          ]}
          rows={rows}
          empty={applied === '' ? '급여 지급일을 선택하세요.' : '조회 결과가 없습니다.'}
        />
        <Pager
          page={page}
          size={payrolls.data ? payrolls.data.size : 20}
          total={payrolls.data ? payrolls.data.total : 0}
          onPage={setPage}
        />
      </section>
      {open && (
        <Drawer title="퇴직금 시뮬레이션" onClose={() => setOpen(false)}>
          <Form
            submit="계산"
            onSubmit={simulate}
            note={result === undefined ? undefined : <span>예상 퇴직금: <Num value={result} /></span>}
          >
            <Field label="퇴직 예정일" required>
              <DateInput value={retirementDate} onChange={setRetirementDate} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
